def branchy(value: int) -> int:
    if value == 0:
        value += 1
    if value == 1:
        value += 1
    if value == 2:
        value += 1
    if value == 3:
        value += 1
    if value == 4:
        value += 1
    if value == 5:
        value += 1
    if value == 6:
        value += 1
    if value == 7:
        value += 1
    if value == 8:
        value += 1
    if value == 9:
        value += 1
    return value
